//! Acceptance criteria of spec node CORE.BUS.PIPE.VALID (AC-1 .. AC-7), plus the fail-closed
//! rules of its Design. Expected outcomes of `params.jsonl` and `real.json` come from
//! `fixtures/core/bus/pipe/valid/make_cases.py`, an independent reference validator in
//! Python; the precondition and limit cases are hand-labelled from the spec's rules. Nothing
//! here is generated by this crate.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use fid_bus::error::{BusError, Code, HiddenCommandReason, NotFoundReason, PreconditionReason, ValidationReason};
use fid_bus::handler::{EntityId, EntityRef, SettingKey, StateView, ValidParams};
use fid_bus::policy::projection::{command_defs, list_requests, RequestBook};
use fid_bus::principal::{
    Channel, ChannelKind, Identity, Principal, PrincipalId, PrincipalKind, PrincipalRef, SessionId, SessionKey,
    SessionTable,
};
use fid_bus::unit::Normalised;
use fid_bus::validate::{
    CommandTable, Compiled, Hooks, NoRoots, RefLookup, TableCache, TableError, Validated, ValidationError,
    MAX_PARAMS_BYTES, MAX_PARAMS_ELEMENTS,
};
use fid_canon::{parse, to_canonical_bytes, CValue, Digest};
use fid_registry::manifest::{command_def as show_manifest_def, show_manifest, ShowParams};
use fid_registry::{check_schema, Catalogue, CommandDecl, CommandDef, ContextTypes, ManifestInForce};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;

const DIR: &str = "fixtures/core/bus/pipe/valid";
const DIGEST: Digest = Digest([7; 32]);

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn read(path: &str) -> Vec<u8> {
    std::fs::read(root().join(path)).unwrap_or_else(|e| panic!("{path}: {e}"))
}

fn fixture(name: &str) -> CValue {
    parse(&read(&format!("{DIR}/{name}"))).unwrap_or_else(|e| panic!("{name}: {e}"))
}

fn get<'a>(v: &'a CValue, k: &str) -> &'a CValue {
    match v {
        CValue::Obj(m) => m.get(k).unwrap_or(&CValue::Null),
        _ => &CValue::Null,
    }
}

fn s(v: &CValue) -> &str {
    match v {
        CValue::Str(s) => s,
        other => panic!("not a string: {other:?}"),
    }
}

fn arr(v: &CValue) -> &[CValue] {
    match v {
        CValue::Arr(a) => a,
        other => panic!("not an array: {other:?}"),
    }
}

fn catalogue() -> Catalogue {
    Catalogue::from_json(&read("fixtures/core/bus/unit/catalogue.json")).unwrap()
}

// ------------------------------------------------------------------ principals

struct TestChannel {
    kind: ChannelKind,
    identity: Identity,
    session: SessionKey,
}

impl Channel for TestChannel {
    fn kind(&self) -> ChannelKind {
        self.kind
    }
    fn authenticated_identity(&self) -> Option<Identity> {
        Some(self.identity.clone())
    }
    fn session(&self) -> &SessionKey {
        &self.session
    }
}

/// The principal the bus derives for a fixture tag (the only way to build one).
fn principal(tag: &str) -> Principal {
    let (kind, subject) = match tag {
        "human" => (ChannelKind::Gui, "alice"),
        "agent" => (ChannelKind::Mcp, "client-1"),
        "replay" => (ChannelKind::Internal, "replay"),
        "recompute" => (ChannelKind::Internal, "recompute"),
        other => panic!("unknown principal tag {other}"),
    };
    let mut table = SessionTable::new();
    let mut identity = Identity::new(PrincipalId::new(subject).unwrap());
    if kind == ChannelKind::Internal {
        identity.acting_for =
            Some(PrincipalRef { kind: PrincipalKind::Human, id: PrincipalId::new("trigger").unwrap() });
    }
    let session = table.open_session(SessionId::new(&format!("{tag}-1")).unwrap()).unwrap();
    table.derive_principal(&TestChannel { kind, identity, session }).unwrap()
}

// ------------------------------------------------------------------ state view

struct View(BTreeMap<EntityId, (EntityId, String, CValue)>);

impl StateView for View {
    fn entity(&self, id: &EntityId) -> Option<EntityRef<'_>> {
        self.0.get(id).map(|(id, kind, body)| EntityRef { id, kind, body })
    }
    fn head(&self) -> Digest {
        Digest([0; 32])
    }
    fn setting(&self, _: &SettingKey) -> Option<CValue> {
        None
    }
}

fn view() -> View {
    let mut m = BTreeMap::new();
    for e in arr(get(&fixture("state.json"), "entities")) {
        let id = EntityId::new(s(get(e, "id"))).unwrap();
        m.insert(id.clone(), (id, s(get(e, "kind")).to_string(), CValue::Null));
    }
    View(m)
}

fn defs() -> Vec<CommandDef> {
    arr(get(&fixture("registry.json"), "commands")).iter().map(|c| CommandDef::from_value(c.clone()).unwrap()).collect()
}

fn table() -> CommandTable {
    CommandTable::build(DIGEST, defs(), catalogue(), &ContextTypes::new()).unwrap()
}

fn def_with(id: &str, params_schema: &str, preconditions: &str) -> CommandDef {
    let json = format!(
        r#"{{"id":"{id}","major":1,"title":"T","description":"D","params_schema":{params_schema},
"result_schema":{{"type":"object"}},"side_effect":"W2","mcp_projection":"never","determinism":"D0",
"idempotency":"none","fs_effect":"none","undo":"head_move","preconditions":{preconditions},
"effects":["TestDone"],"algorithms":[],"exposure":["cli"],
"lifecycle":{{"state":"active","since":"2026-01-01"}},"web":"available"}}"#
    );
    CommandDef::from_value(parse(json.as_bytes()).unwrap()).unwrap()
}

fn obj(pairs: &[(&str, CValue)]) -> CValue {
    CValue::Obj(pairs.iter().map(|(k, v)| (k.to_string(), v.clone())).collect())
}

fn text(v: &str) -> CValue {
    CValue::Str(v.to_string())
}

fn split(cmd: &str) -> (&str, u32) {
    let (id, major) = cmd.rsplit_once('@').unwrap();
    (id, major.parse().unwrap())
}

// ------------------------------------------------------------------ tests

/// Every fixture schema passes the registry's own schema checker and compiles here.
#[test]
fn fixture_registry_is_a_valid_registry() {
    let cat = catalogue();
    for d in defs() {
        let issues = check_schema(&d.params_schema, &cat);
        assert!(issues.is_empty(), "{}@{}: {issues:?}", d.id, d.major);
    }
    assert_eq!(table().compile_errors(), Vec::<(String, String)>::new());
}

/// AC-1: an unknown ID, a removed major and an unknown major are `not_found`.
#[test]
fn ac1_not_found() {
    let t = table();
    let human = principal("human");
    for (id, major, reason) in [
        ("nope.cmd", 1, NotFoundReason::UnknownCommand),
        ("t.gone", 1, NotFoundReason::RemovedMajor),
        ("t.shapes", 9, NotFoundReason::UnknownMajor),
        ("T.Shapes", 1, NotFoundReason::UnknownCommand),
    ] {
        match t.resolve(id, major, &human) {
            Err(BusError::NotFound(r, d)) => {
                assert_eq!(r, reason, "{id}@{major}");
                assert!(d.as_untrusted_str().contains(&format!("@{major}")), "names the major");
            }
            other => panic!("{id}@{major}: {other:?}"),
        }
    }
    assert!(t.resolve("t.gone", 2, &human).is_ok(), "another major of a removed one resolves");
}

/// AC-2: a hidden major is `hidden_command` for anyone but the replay engine, which proceeds
/// to validation.
#[test]
fn ac2_hidden() {
    let t = table();
    for tag in ["human", "agent", "recompute"] {
        match t.resolve("t.hidden", 1, &principal(tag)) {
            Err(BusError::HiddenCommand(HiddenCommandReason::HiddenMajor, _)) => {}
            other => panic!("{tag}: {other:?}"),
        }
    }
    let replay = principal("replay");
    assert_eq!(replay.kind(), PrincipalKind::System);
    let r = t.resolve("t.hidden", 1, &replay).unwrap();
    assert!(r.validate_value(&obj(&[("n", CValue::Num(1.0))]), &view()).is_ok());
    let e = r.validate_value(&obj(&[("n", text("x"))]), &view()).unwrap_err();
    assert_eq!((e.pointer.to_string().as_str(), e.keyword), ("/n", "type"));
}

/// A deprecated major resolves and tells the surface its successor.
#[test]
fn deprecated_major_resolves_with_notice() {
    let t = table();
    let r = t.resolve("t.old", 1, &principal("agent")).unwrap();
    let d = r.deprecation().unwrap();
    assert_eq!(d.replaced_by.unwrap().to_string(), "t.old@2");
    assert_eq!(d.remove_after.unwrap().to_string(), "2027-06-01");
    assert!(t.resolve("t.old", 2, &principal("agent")).unwrap().deprecation().is_none());
}

fn check_validated(case: &str, got: &Validated, exp: &CValue, params: &CValue) {
    assert_eq!(got.params().value(), get(exp, "params"), "{case}: normalised parameters");
    assert_eq!(got.entry_params(), params, "{case}: the entry keeps the document as entered");
    let want = arr(get(exp, "literals"));
    assert_eq!(got.literals().len(), want.len(), "{case}: literal count");
    for (g, w) in got.literals().iter().zip(want) {
        assert_eq!(g.pointer.to_string(), s(get(w, "pointer")), "{case}");
        assert_eq!(format!("0x{:016x}", g.normalised.si_bits()), s(get(w, "si_bits")), "{case}");
        let lit = g.normalised.literal();
        assert_eq!((lit.value().as_str(), lit.unit().as_str()), (s(get(w, "value")), s(get(w, "unit"))), "{case}");
    }
    let algs: Vec<String> = got.algorithms().iter().map(|a| a.to_string()).collect();
    let want_algs: Vec<String> = if want.is_empty() { vec![] } else { vec!["core.unit.normalise@1.0.0".into()] };
    assert_eq!(algs, want_algs, "{case}");
}

fn check_refusal(case: &str, got: &ValidationError, exp: &CValue) {
    assert_eq!(got.pointer.to_string(), s(get(exp, "pointer")), "{case}: pointer");
    assert_eq!(got.keyword, s(get(exp, "keyword")), "{case}: keyword");
    assert_eq!(got.reason.as_str(), s(get(exp, "reason")), "{case}: reason");
    let bus = got.to_bus_error();
    assert_eq!((bus.code(), bus.reason()), (Code::Validation, s(get(exp, "reason"))), "{case}");
}

/// AC-3 (and AC-4, AC-5 cases): every parameter document of `params.jsonl` gives the
/// expected outcome, pointer, keyword and normalised values, through both the value and the
/// text entry points.
#[test]
fn ac3_params_fixture() {
    let t = table();
    let v = view();
    let text_rows = String::from_utf8(read(&format!("{DIR}/params.jsonl"))).unwrap();
    let mut n = 0;
    for line in text_rows.lines() {
        n += 1;
        let row = parse(line.as_bytes()).unwrap();
        let case = s(get(&row, "case"));
        let (id, major) = split(s(get(&row, "command")));
        let exp = get(&row, "expect");
        let params = get(&row, "params");
        let resolved = t.resolve(id, major, &principal(s(get(&row, "principal"))));
        let code = get(exp, "code");
        if *code == text("not_found") || *code == text("hidden_command") {
            let e = resolved.unwrap_err();
            assert_eq!((e.code().as_str(), e.reason()), (s(code), s(get(exp, "reason"))), "{case}");
            continue;
        }
        let r = resolved.unwrap_or_else(|e| panic!("{case}: {e}"));
        let got = match get(&row, "params_text") {
            // Rows whose exact text matters (integers beyond 2^53): the text entry point only.
            CValue::Str(text) => r.validate_json(text.as_bytes(), &v),
            _ => {
                let by_value = r.validate_value(params, &v);
                let by_text = r.validate_json(&to_canonical_bytes(params).unwrap(), &v);
                assert_eq!(by_value, by_text, "{case}: value and text entry points agree");
                by_value
            }
        };
        match (s(get(exp, "outcome")), got) {
            ("ok", Ok(got)) => check_validated(case, &got, exp, params),
            ("error", Err(got)) => check_refusal(case, &got, exp),
            (want, got) => panic!("{case}: expected {want}, got {got:?}"),
        }
    }
    assert!(n >= 60, "AC-3 needs at least 60 documents, found {n}");
}

/// AC-4: an `x-ref` to a missing entity and one to an entity of the wrong kind.
#[test]
fn ac4_bad_reference() {
    let t = table();
    let r = t.resolve("t.measure", 1, &principal("human")).unwrap();
    for id in ["F9", "D1"] {
        let p = obj(&[("length", CValue::Num(1.0)), ("feature", text(id))]);
        let e = validate(&r, &p);
        assert_eq!(e.code(), Code::Validation);
        assert_eq!(e.reason(), "bad_reference", "{id}");
    }
}

fn validate(r: &fid_bus::validate::Resolved<'_>, p: &CValue) -> BusError {
    fid_bus::validate_params(r, p, &view()).unwrap_err()
}

/// AC-5: `{"value":"10.1","unit":"mm"}` reaches the handler as the SI value and the entry
/// keeps the literal. The expected bits are the oracle's (`literal_length`).
#[test]
fn ac5_literal_normalised_and_kept() {
    let rows = String::from_utf8(read(&format!("{DIR}/params.jsonl"))).unwrap();
    let row = rows.lines().map(|l| parse(l.as_bytes()).unwrap()).find(|r| *get(r, "case") == text("literal_length"));
    let row = row.unwrap();
    let bits = s(get(&arr(get(get(&row, "expect"), "literals"))[0], "si_bits")).to_string();
    let t = table();
    let r = t.resolve("t.measure", 1, &principal("human")).unwrap();
    let literal = obj(&[("unit", text("mm")), ("value", text("10.1"))]);
    let p = obj(&[("length", literal.clone())]);
    let got = r.validate_value(&p, &view()).unwrap();
    match get(got.params().value(), "length") {
        CValue::Num(x) => assert_eq!(format!("0x{:016x}", x.to_bits()), bits),
        other => panic!("{other:?}"),
    }
    assert_eq!(get(got.entry_params(), "length"), &literal);
    let rec = &got.literals()[0];
    assert_eq!(rec.pointer.to_string(), "/length");
    assert_eq!(rec.normalised.literal().to_value(), literal);
    assert_eq!(rec.normalised.algorithm().to_string(), "core.unit.normalise@1.0.0");
}

/// AC-6: a false precondition and one that runs past its step bound are both
/// `precondition`, the second with `step_bound_exceeded`. Validation runs no handler and
/// writes nothing, so nothing can be journaled.
#[test]
fn ac6_preconditions() {
    let t = table();
    let r = t.resolve("t.guarded", 1, &principal("human")).unwrap();
    let run = |limit: f64, items: Vec<f64>| {
        let p =
            obj(&[("limit", CValue::Num(limit)), ("items", CValue::Arr(items.into_iter().map(CValue::Num).collect()))]);
        let v = r.validate_value(&p, &view()).unwrap();
        r.check_preconditions(v.params(), &NoRoots)
    };
    match run(0.0, vec![1.0]) {
        Err(BusError::Precondition(PreconditionReason::False, d)) => {
            assert!(d.as_untrusted_str().contains("t.guarded.limit_positive"), "names the predicate")
        }
        other => panic!("{other:?}"),
    }
    match run(1.0, vec![1.0; 50]) {
        Err(BusError::Precondition(PreconditionReason::StepBoundExceeded, d)) => {
            assert!(d.as_untrusted_str().contains("t.guarded.items_nonnegative"))
        }
        other => panic!("{other:?}"),
    }
    match run(1.0, vec![1.0, -1.0]) {
        Err(BusError::Precondition(PreconditionReason::False, d)) => {
            assert!(d.as_untrusted_str().contains("t.guarded.items_nonnegative"))
        }
        other => panic!("{other:?}"),
    }
    assert_eq!(run(1.0, vec![0.0, 2.0]), Ok(()));
}

/// `x-quantity` with its own numeric bounds, and shared through `$ref` without numeric
/// keywords elsewhere, compiles.
#[test]
fn quantity_with_own_bounds_compiles() {
    for schema in [
        r#"{"type":"number","x-quantity":"length","minimum":0,"multipleOf":0.5}"#,
        r##"{"$defs":{"len":{"type":"number","x-quantity":"length","minimum":0}},"properties":{"a":{"$ref":"#/$defs/len"},"b":{"$ref":"#/$defs/len"}}}"##,
        r#"{"properties":{"a":{"x-quantity":"length","minimum":0},"n":{"type":"integer","minimum":1}}}"#,
        r#"{"type":"array","items":{"x-quantity":"length","maximum":2},"contains":{"type":"number"}}"#,
    ] {
        assert!(Compiled::compile(&parse(schema.as_bytes()).unwrap()).is_ok(), "{schema}");
    }
}

/// A precondition reading a context root the caller does not supply fails closed.
#[test]
fn precondition_with_missing_root_is_false() {
    let d = def_with("t.ctx", r#"{"type":"object"}"#, r#"[{"expr":"true","bound":5,"message_key":"t.ok"}]"#);
    let t = CommandTable::build(DIGEST, vec![d], catalogue(), &ContextTypes::new()).unwrap();
    let r = t.resolve("t.ctx", 1, &principal("human")).unwrap();
    let v = r.validate_value(&obj(&[]), &view()).unwrap();
    assert_eq!(r.check_preconditions(v.params(), &NoRoots), Ok(()));
    let bad = def_with("t.bad", r#"{"type":"object"}"#, r#"[{"expr":"doc.x == 1","bound":5,"message_key":"t.k"}]"#);
    let t = CommandTable::build(DIGEST, vec![bad], catalogue(), &ContextTypes::new()).unwrap();
    assert_eq!(t.compile_errors().len(), 1, "an untyped root does not type-check");
    let r = t.resolve("t.bad", 1, &principal("human")).unwrap();
    let v = r.validate_value(&obj(&[]), &view()).unwrap();
    let e = r.check_preconditions(v.params(), &NoRoots).unwrap_err();
    assert_eq!((e.code(), e.reason()), (Code::Precondition, "false"));
}

/// AC-7: a 17 MiB parameter document is `validation/input_limit`; so is one nested 65 deep
/// or holding more than 2^20 values and keys, through both entry points.
#[test]
fn ac7_input_limit() {
    let t = table();
    let r = t.resolve("t.free", 1, &principal("human")).unwrap();
    let v = view();
    let limit = |e: ValidationError| {
        assert_eq!(
            (e.reason, e.keyword, e.pointer.to_string()),
            (ValidationReason::InputLimit, "input_limit", "".into())
        );
        assert_eq!(e.to_bus_error().reason(), "input_limit");
    };
    let big = format!("{{\"a\":\"{}\"}}", "x".repeat(17 * 1024 * 1024));
    limit(r.validate_json(big.as_bytes(), &v).unwrap_err());
    let big_value = obj(&[("a", text(&"x".repeat(MAX_PARAMS_BYTES)))]);
    limit(r.validate_value(&big_value, &v).unwrap_err());
    let nest = |levels: usize| format!("{{\"a\":{}{}}}", "[".repeat(levels - 1), "]".repeat(levels - 1));
    assert!(r.validate_json(nest(64).as_bytes(), &v).is_ok(), "64 levels are accepted");
    limit(r.validate_json(nest(65).as_bytes(), &v).unwrap_err());
    let deep = parse(nest(64).as_bytes()).unwrap();
    assert!(r.validate_value(&deep, &v).is_ok());
    limit(r.validate_value(&obj(&[("w", deep)]), &v).unwrap_err());
    let many = format!("{{\"a\":[{}]}}", vec!["0"; MAX_PARAMS_ELEMENTS].join(","));
    limit(r.validate_json(many.as_bytes(), &v).unwrap_err());
}

/// Other parse failures are `validation/schema` under the pseudo-keyword `json`.
#[test]
fn bad_json_is_refused() {
    let t = table();
    let r = t.resolve("t.free", 1, &principal("human")).unwrap();
    for bad in [&b"{\"a\":1,\"a\":2}"[..], b"{\"a\":", b"\xff", b"{\"a\":1e999}"] {
        let e = r.validate_json(bad, &view()).unwrap_err();
        assert_eq!((e.reason, e.keyword), (ValidationReason::Schema, "json"), "{bad:?}");
    }
    let e = r.validate_value(&obj(&[("a", CValue::I64(1))]), &view()).unwrap_err();
    assert_eq!((e.keyword, e.pointer.to_string().as_str()), ("type", "/a"), "no non-JSON number forms");
}

struct NoHooks;

impl Hooks for NoHooks {
    fn literal(&self, _: &str, _: &CValue) -> Result<Normalised, BusError> {
        Err(BusError::Validation(ValidationReason::UnitMismatch, fid_bus::error::Detail::new("none")))
    }
    fn entity(&self, _: &str) -> RefLookup {
        RefLookup::Missing
    }
}

/// Exponential schemas stop at the step budget or the nesting limit with `input_limit`, and
/// no `not` or `anyOf` can turn that into a pass. Run on a thread with a 2 MiB stack (the
/// test-thread default) so the nesting limit is shown to fit it even in a debug build.
#[test]
fn evaluation_is_bounded_and_fails_closed() {
    // 1 MiB: the stack the nesting limit is pinned to fit, even in a debug build (NODE.md).
    std::thread::Builder::new().stack_size(1024 * 1024).spawn(bounded_cases).unwrap().join().unwrap();
}

/// The step budget charges every object member and array element a keyword looks at, so an
/// exponential schema over a wide object stops with `input_limit` in bounded time (review of
/// #341: before, each application walked every member for one step).
#[test]
fn wide_documents_are_charged_per_member() {
    // d0 walks every member; d(k) applies d(k-1) twice; d12 applies d0 4096 times.
    let mut defs = vec![r#""d0":{"additionalProperties":true,"propertyNames":true}"#.to_string()];
    for k in 1..=12 {
        defs.push(format!(r##""d{k}":{{"allOf":[{{"$ref":"#/$defs/d{p}"}},{{"$ref":"#/$defs/d{p}"}}]}}"##, p = k - 1));
    }
    let schema = format!(r##"{{"$defs":{{{}}},"$ref":"#/$defs/d12"}}"##, defs.join(","));
    let c = Compiled::compile(&parse(schema.as_bytes()).unwrap()).unwrap();
    let wide = CValue::Obj((0..100_000).map(|i| (format!("m{i}"), CValue::Num(0.0))).collect());
    let started = std::time::Instant::now();
    let e = c.evaluate(&wide, &NoHooks).unwrap_err();
    assert_eq!((e.keyword, e.reason), ("input_limit", ValidationReason::InputLimit));
    assert!(started.elapsed() < std::time::Duration::from_secs(60), "bounded time: {:?}", started.elapsed());
    let arrays = CValue::Arr(vec![CValue::Num(0.0); 100_000]);
    let items = r##"{"$defs":{"a":{"items":true}},"allOf":[{"$ref":"#/$defs/a"},{"$ref":"#/$defs/a"}]}"##;
    let c = Compiled::compile(&parse(items.as_bytes()).unwrap()).unwrap();
    assert!(c.evaluate(&arrays, &NoHooks).is_ok(), "a few walks of a wide array fit the budget");
}

/// `format: "regex"` compiles each string: at most 64 checks per document, each charged by
/// pattern size.
#[test]
fn regex_format_checks_are_capped() {
    let c =
        Compiled::compile(&parse(br#"{"type":"array","items":{"type":"string","format":"regex"}}"#).unwrap()).unwrap();
    let doc = |n: usize| CValue::Arr(vec![text("^[a-z]+$"); n]);
    assert!(c.evaluate(&doc(64), &NoHooks).is_ok());
    let e = c.evaluate(&doc(65), &NoHooks).unwrap_err();
    assert_eq!((e.keyword, e.reason), ("input_limit", ValidationReason::InputLimit));
}

/// The hand-labelled ECMA-262 table: every row's verdict (match, no match, refused).
#[test]
fn ecma_table() {
    let table = fixture("ecma_table.json");
    let mut n = 0;
    for row in arr(get(&table, "rows")) {
        n += 1;
        let pattern = s(get(row, "pattern"));
        let got = match fid_bus::validate::Pattern::compile(pattern) {
            Err(_) => "refused",
            Ok(p) if p.is_match(s(get(row, "input"))) => "match",
            Ok(_) => "no_match",
        };
        assert_eq!(got, s(get(row, "verdict")), "{pattern:?} on {:?}", get(row, "input"));
    }
    assert!(n >= 60);
}

/// The hand-labelled JSON Schema 2020-12 cases.
#[test]
fn spec_cases() {
    let cases = fixture("spec_cases.json");
    let mut n = 0;
    for g in arr(get(&cases, "groups")) {
        let c = Compiled::compile(get(g, "schema")).unwrap_or_else(|e| panic!("{}: {e}", s(get(g, "name"))));
        for t in arr(get(g, "tests")) {
            n += 1;
            let valid = c.evaluate(get(t, "data"), &NoHooks).is_ok();
            assert_eq!(CValue::Bool(valid), *get(t, "valid"), "{} / {}", s(get(g, "name")), s(get(t, "note")));
        }
    }
    assert!(n >= 50);
}

fn bounded_cases() {
    for schema in [
        r##"{"anyOf":[{"$ref":"#"},{"$ref":"#"}]}"##,
        r##"{"not":{"anyOf":[{"$ref":"#"},{"$ref":"#"}]}}"##,
        r##"{"anyOf":[{"not":{"$ref":"#"}},true]}"##,
        r##"{"$defs":{"a":{"oneOf":[{"$ref":"#/$defs/b"},{"$ref":"#/$defs/b"}]},"b":{"anyOf":[{"$ref":"#/$defs/a"},{"$ref":"#/$defs/a"}]}},"$ref":"#/$defs/a"}"##,
    ] {
        let c = Compiled::compile(&parse(schema.as_bytes()).unwrap()).unwrap();
        let e = c.evaluate(&obj(&[]), &NoHooks).unwrap_err();
        assert_eq!((e.keyword, e.reason), ("input_limit", ValidationReason::InputLimit), "{schema}");
    }
    // A wide but legitimate document stays well inside the budget.
    let c = Compiled::compile(&parse(br#"{"type":"array","items":{"type":"integer","minimum":0}}"#).unwrap()).unwrap();
    assert!(c.evaluate(&CValue::Arr(vec![CValue::Num(1.0); 100_000]), &NoHooks).is_ok());
}

/// A schema the validator cannot apply in full refuses every call of its command with
/// `validation/schema` (never `internal`, never a pass).
#[test]
fn uncompilable_schema_fails_closed() {
    let schemas = [
        r#"{"type":"object","x-unknown":1}"#,
        r#"{"type":"string","format":"email"}"#,
        r##"{"$dynamicRef":"#meta"}"##,
        r##"{"$ref":"#/properties"}"##,
        r##"{"$ref":"https://example.com/s.json"}"##,
        r#"{"pattern":"(?=a)"}"#,
        r#"{"pattern":"\\p{L}"}"#,
        r#"{"patternProperties":{"(a)\\1":true}}"#,
        r#"{"$schema":"http://json-schema.org/draft-07/schema#"}"#,
        r#"{"items":[{}]}"#,
        r#"{"properties":{"a":{"$schema":"https://json-schema.org/draft/2020-12/schema"}}}"#,
        r#"{"multipleOf":0}"#,
        // x-quantity behind an applicator with numeric keywords elsewhere (review of #341).
        r##"{"$defs":{"len":{"type":"number","x-quantity":"length"}},"$ref":"#/$defs/len","minimum":0}"##,
        r#"{"allOf":[{"x-quantity":"length"},{"maximum":5}]}"#,
        r#"{"x-quantity":"length","allOf":[{"multipleOf":0.5}]}"#,
        r#"{"anyOf":[{"x-quantity":"length","minimum":0},{"type":"integer","minimum":5}]}"#,
        r#"{"oneOf":[{"x-quantity":"length"}],"exclusiveMinimum":0}"#,
        r#"{"if":{"x-quantity":"length"},"then":{"exclusiveMaximum":1}}"#,
        r#"{"properties":{"a":{"dependentSchemas":{"b":{"minimum":1}},"x-quantity":"length"}}}"#,
        // x-quantity under contains or not: those literals would never be normalised.
        r#"{"contains":{"x-quantity":"length"}}"#,
        r##"{"$defs":{"q":{"x-quantity":"length"}},"contains":{"allOf":[{"$ref":"#/$defs/q"}]}}"##,
        r#"{"not":{"x-quantity":"length"}}"#,
        // Pattern classes with a bare hyphen.
        r#"{"pattern":"^[^--/]+$"}"#,
        r#"{"patternProperties":{"[a--]":true}}"#,
    ];
    let defs: Vec<CommandDef> =
        schemas.iter().enumerate().map(|(i, s)| def_with(&format!("t.c{i}"), s, "[]")).collect();
    let t = CommandTable::build(DIGEST, defs, catalogue(), &ContextTypes::new()).unwrap();
    assert_eq!(t.compile_errors().len(), schemas.len(), "{:?}", t.compile_errors());
    for (i, schema) in schemas.iter().enumerate() {
        let r = t.resolve(&format!("t.c{i}"), 1, &principal("human")).unwrap();
        let e = r.validate_value(&obj(&[]), &view()).unwrap_err();
        assert_eq!((e.reason, e.keyword), (ValidationReason::Schema, "schema"), "{schema}");
        assert_eq!(e.to_bus_error().code(), Code::Validation);
    }
}

fn live_defs() -> BTreeMap<String, CommandDef> {
    let mut all = command_defs().unwrap();
    all.push(show_manifest_def().unwrap());
    all.into_iter().map(|d| (format!("{}@{}", d.id, d.major), d)).collect()
}

/// Real command schemas with real documents: the oracle's copies equal the live
/// definitions, and every recorded parameter and result document gives the oracle's outcome.
#[test]
fn real_command_schemas() {
    let real = fixture("real.json");
    let live = live_defs();
    let CValue::Obj(copies) = get(&real, "commands") else { panic!("commands") };
    assert_eq!(copies.len(), live.len());
    for (cmd, copy) in copies {
        let d = live.get(cmd).unwrap_or_else(|| panic!("{cmd} is not a live command"));
        assert_eq!(get(copy, "params_schema"), &d.params_schema, "{cmd}: params_schema copy is stale");
        assert_eq!(get(copy, "result_schema"), &d.result_schema, "{cmd}: result_schema copy is stale");
    }
    let t = CommandTable::build(DIGEST, live.values().cloned().collect(), catalogue(), &ContextTypes::new()).unwrap();
    assert!(t.compile_errors().is_empty(), "{:?}", t.compile_errors());
    let mut n = 0;
    for c in arr(get(&real, "cases")) {
        n += 1;
        let case = s(get(c, "case"));
        let cmd = s(get(c, "command"));
        let doc = get(c, "document");
        let exp = get(c, "expect");
        let got: Result<(), ValidationError> = if s(get(c, "target")) == "params" {
            let (id, major) = split(cmd);
            let r = t.resolve(id, major, &principal("human")).unwrap();
            r.validate_value(doc, &view()).map(|_| ())
        } else {
            let schema = Compiled::compile(&live[cmd].result_schema).unwrap();
            schema.evaluate(doc, &NoHooks).map(|_| ()).map_err(ValidationError::from)
        };
        match (s(get(exp, "outcome")), got) {
            ("ok", Ok(())) => {}
            ("error", Err(e)) => check_refusal(case, &e, exp),
            (want, got) => panic!("{case}: expected {want}, got {got:?}"),
        }
    }
    assert!(n >= 30);
}

/// Results the real commands produce satisfy their result schemas.
#[test]
fn real_results_validate() {
    let def = show_manifest_def().unwrap();
    let m = ManifestInForce::new(&[CommandDecl::from_def(&def)], Catalogue::geo_frame().unwrap()).unwrap();
    let result = show_manifest(&m, &ShowParams { full: true, check: None }).unwrap();
    assert!(Compiled::compile(&def.result_schema).unwrap().evaluate(&result, &NoHooks).is_ok());

    let list = live_defs().remove("request.list_requests@1").unwrap();
    let params = obj(&[("state", text("pending"))]);
    let t = CommandTable::build(DIGEST, vec![list.clone()], catalogue(), &ContextTypes::new()).unwrap();
    let r = t.resolve("request.list_requests", 1, &principal("agent")).unwrap();
    let v = r.validate_value(&params, &view()).unwrap();
    let result = list_requests(&RequestBook::new(), &principal("agent"), v.params().value()).unwrap();
    assert!(Compiled::compile(&list.result_schema).unwrap().evaluate(&result, &NoHooks).is_ok());
}

/// The cache keeps one table per manifest digest and refuses a table of another digest.
#[test]
fn table_cache() {
    let mut cache = TableCache::new();
    let a = cache.get_or_build(DIGEST, || Ok(table())).unwrap();
    let b = cache.get_or_build(DIGEST, || panic!("must not rebuild")).unwrap();
    assert!(Arc::ptr_eq(&a, &b));
    let other = Digest([9; 32]);
    assert_eq!(cache.get_or_build(other, || Ok(table())).unwrap_err(), TableError::DigestMismatch);
    for i in 0..6u8 {
        let d = Digest([i; 32]);
        cache.get_or_build(d, || CommandTable::build(d, defs(), catalogue(), &ContextTypes::new())).unwrap();
    }
    assert!(cache.get(&DIGEST).is_none(), "the oldest table is dropped");
    assert!(cache.get(&Digest([5; 32])).is_some());
}

/// A handler only ever sees parameters through `ValidParams`, which validation builds.
#[test]
fn validated_params_are_valid_params() {
    let t = table();
    let r = t.resolve("t.shapes", 1, &principal("human")).unwrap();
    let p = obj(&[("name", text("ab")), ("count", CValue::Num(1.0))]);
    let v: ValidParams = r.validate_value(&p, &view()).unwrap().into_params();
    assert_eq!(v.value(), &p);
}
